import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.jdbc.support.KeyHolder;
import org.springframework.stereotype.Repository;

/** The stored plans, kept per sheet, and the dates each has made a claim for. */
@Repository
public class PlanRepository {

    private final JdbcTemplate jdbc;
    private final SheetRepository sheets;

    public PlanRepository(JdbcTemplate jdbc, SheetRepository sheets) {
        this.jdbc = jdbc;
        this.sheets = sheets;
    }

    /** The sheet's plans in the order added, each with how many claims it has made; as they stood at the end of the
     *  date when one is given (only those added, and claims made, while the sheet's today was on or before it). */
    public List<Plan> list(String sheetId, LocalDate asOf) {
        Date until = asOf == null ? null : Date.valueOf(asOf);
        return jdbc.query("SELECT p.id, p.person_id, p.amount, p.start_date, p.every_days, p.end_date,"
                + " (SELECT COUNT(*) FROM plan_claim c WHERE c.plan_id = p.id"
                + " AND (CAST(? AS DATE) IS NULL OR c.made_on IS NULL OR c.made_on <= ?)) AS generated"
                + " FROM plan p WHERE p.sheet_id = ? AND (CAST(? AS DATE) IS NULL OR p.added_on IS NULL OR p.added_on <= ?)"
                + " ORDER BY p.id",
                (rs, n) -> new Plan(rs.getLong("id"), rs.getLong("person_id"), rs.getBigDecimal("amount").setScale(2),
                        rs.getObject("start_date", LocalDate.class), rs.getInt("every_days"),
                        rs.getObject("end_date", LocalDate.class), rs.getInt("generated")),
                until, until, sheetId, until, until);
    }

    /** Stores the plan for the person; the plan as stored. */
    public Plan add(String sheetId, long personId, PlanValues values) {
        KeyHolder key = new GeneratedKeyHolder();
        jdbc.update((con) -> {
            var ps = con.prepareStatement("INSERT INTO plan (sheet_id, person_id, amount, start_date, every_days, end_date, added_on)"
                    + " VALUES (?, ?, ?, ?, ?, ?, ?)", new String[] { "id" });
            ps.setString(1, sheetId);
            ps.setLong(2, personId);
            ps.setBigDecimal(3, values.amount());
            ps.setDate(4, Date.valueOf(values.start()));
            ps.setInt(5, values.every());
            ps.setDate(6, Date.valueOf(values.end()));
            ps.setDate(7, Date.valueOf(sheets.today(sheetId)));
            return ps;
        }, key);
        return new Plan(key.getKey().longValue(), personId, values.amount(), values.start(), values.every(), values.end(), 0);
    }

    /** Whether the plan has made a claim for the date. */
    public boolean made(long planId, LocalDate date) {
        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM plan_claim WHERE plan_id = ? AND plan_date = ?", Integer.class,
                planId, Date.valueOf(date));
        return n != null && n > 0;
    }

    /** Records that the plan made the claim for the date. */
    public void recordMade(String sheetId, long planId, LocalDate date, long claimId) {
        jdbc.update("INSERT INTO plan_claim (plan_id, plan_date, claim_id, made_on) VALUES (?, ?, ?, ?)", planId,
                Date.valueOf(date), claimId, Date.valueOf(sheets.today(sheetId)));
    }
}
import { useState, type ChangeEvent } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { PeopleHead, PersonRow } from '../../slots/defs/personRow';
import { SheetPage } from '../../slots/defs/sheetPage';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { claimsKey } from '../claims/claims';
import { peopleKey, type Person } from '../people/people';
import { plansKey, usePlans, type Plan } from './plans';

function PlansHead() {
  return <th>Plans</th>;
}

type PlanForm = { amount: string; start: string; every: string; end: string };
const EMPTY: PlanForm = { amount: '', start: '', every: '', end: '' };

/** A person's plans (amount, start, every N days, end, and how many claims each has made so far), in the order added,
 *  and the form that adds one. The server refuses a bad amount or interval, or an end before the start: the row's
 *  plan error shows, until the form is changed or submitted again. */
function PersonPlans({ sheetId, user, person }: { sheetId: string; user: string; person: Person }) {
  const plans = usePlans(sheetId);
  const queryClient = useQueryClient();
  const [form, setForm] = useState<PlanForm>(EMPTY);

  const submit = useSubmitOnce();
  const add = useMutation({
    mutationFn: (f: PlanForm) =>
      postJson<Plan>(`/api/sheets/${encodeURIComponent(sheetId)}/people/${person.id}/plans`, { ...f, by: user }),
    onSuccess: () => {
      setForm(EMPTY);
      return queryClient.invalidateQueries({ queryKey: plansKey(sheetId) });
    },
    onSettled: submit.end,
  });

  const change = (key: keyof PlanForm) => (e: ChangeEvent<HTMLInputElement>) => {
    setForm({ ...form, [key]: e.target.value });
    add.reset();
  };
  const mine = (plans.data ?? []).filter((p) => p.personId === person.id);

  return (
    <td>
      <ul>
        {mine.map((p) => (
          <li key={p.id} data-testid={`plan-row-${p.id}`}>
            {p.amount} every {p.every} days from {p.start} to {p.end}; made{' '}
            <span data-testid="plan-generated">{p.generated}</span>
          </li>
        ))}
      </ul>
      <form
        onSubmit={(e) => {
          e.preventDefault();
          if (!submit.begin()) return;
          add.reset();
          add.mutate(form);
        }}
      >
        <input data-testid="plan-form-amount" placeholder="Amount" size={7} value={form.amount} onChange={change('amount')} />{' '}
        <input data-testid="plan-form-start" type="date" value={form.start} onChange={change('start')} />{' '}
        <input data-testid="plan-form-every" placeholder="Every N days" size={4} value={form.every} onChange={change('every')} />{' '}
        <input data-testid="plan-form-end" type="date" value={form.end} onChange={change('end')} />{' '}
        <button type="submit" data-testid="plan-form-submit" disabled={add.isPending}>
          Add plan
        </button>
        {add.isError && <span data-testid="plan-error"> Could not add this plan.</span>}
      </form>
    </td>
  );
}

type Generated = { made: number };

/** The generate button: for every plan on the sheet, in the order added, a DRAFT claim of the plan's amount for each
 *  plan date (the start, then every N days) up to its end and the sheet's today that it has made none for yet, by the
 *  claim form's rules (a date they refuse is skipped, and tried again next time). Shows how many were made; the count
 *  is cleared while a new press runs. */
function GeneratePlans({ sheetId, user }: { sheetId: string; user: string }) {
  const queryClient = useQueryClient();
  const submit = useSubmitOnce();
  const generate = useMutation({
    mutationFn: () => postJson<Generated>(`/api/sheets/${encodeURIComponent(sheetId)}/generate-plans`, { by: user }),
    onSuccess: () => {
      void queryClient.invalidateQueries({ queryKey: peopleKey(sheetId) });
      void queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) });
      void queryClient.invalidateQueries({ queryKey: plansKey(sheetId) });
    },
    onSettled: submit.end,
  });

  return (
    <p>
      <button
        type="button"
        data-testid="plan-generate"
        disabled={generate.isPending}
        onClick={() => {
          if (!submit.begin()) return;
          generate.reset();
          generate.mutate();
        }}
      >
        Generate plan claims
      </button>
      {generate.isSuccess && (
        <>
          {' '}
          Made <span data-testid="plan-generated-count">{generate.data.made}</span>
        </>
      )}
      {generate.isError && <span data-testid="plan-generate-error"> Could not generate the plans' claims.</span>}
    </p>
  );
}

export const contributions = [
  PeopleHead.fill({ order: 65, Component: PlansHead }),
  PersonRow.fill({ order: 65, Component: PersonPlans }),
  SheetPage.fill({ order: 24.5, Component: GeneratePlans }),
];
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

/** A person's plan: a claim of the amount every `every` days from `start` up to `end`, and how many claims it has
 *  made so far. */
export type Plan = { id: number; personId: number; amount: string; start: string; every: number; end: string; generated: number };

export const plansKey = (sheetId: string) => ['sheet', sheetId, 'plans'];

/** Every plan on the sheet, in the order added. */
export function usePlans(sheetId: string) {
  return useQuery({
    queryKey: plansKey(sheetId),
    queryFn: () => getJson<Plan[]>(`/api/sheets/${encodeURIComponent(sheetId)}/plans`),
  });
}

